def _aoss_client(auth):
    return auth.session.client('opensearchserverless')

def create_opensearch_serverless(auth, name, tags=None) -> dict:
    'Create an OpenSearch Serverless collection for vector search (used by Bedrock KB).'
    client = _aoss_client(auth)
    tag_list = [{'key': k, 'value': v} for k, v in (tags or {}).items()]
    # Encryption policy
    try:
        client.create_security_policy(
            name=f'{name}-enc',
            type='encryption',
            policy=json.dumps({'Rules': [{'ResourceType': 'collection',
                                          'Resource': [f'collection/{name}']}],
                               'AWSOwnedKey': True}),
        )
    except client.exceptions.ConflictException:
        pass
    # Network policy — public access for endpoint resolution
    try:
        client.create_security_policy(
            name=f'{name}-net',
            type='network',
            policy=json.dumps([{'Rules': [{'ResourceType': 'collection',
                                           'Resource': [f'collection/{name}']},
                                          {'ResourceType': 'dashboard',
                                           'Resource': [f'collection/{name}']}],
                                'AllowFromPublic': True}]),
        )
    except client.exceptions.ConflictException:
        pass
    try:
        resp = client.create_collection(name=name, type='VECTORSEARCH', tags=tag_list)
        return resp['createCollectionDetail']
    except client.exceptions.ConflictException:
        return client.batch_get_collection(names=[name])['collectionDetails'][0]

